head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/



	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: showObj----//

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/stf.js"); // showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)include("../js/utils.js");include("../js/session.js");// 세션정보를 얻기위한 함수사용include("../js/list_common.js");include("../js/common.js");include("../js/buttonSet.js");include("../js/PopupCalendar.js");include("../js/json2.js");include("../js/report.js");scwin.vScrenID = "ULDSTF05235.gfm"; scwin.fn_GetPar, scwin.fn_SetPar; scwin.vBzProcsNo; scwin.vListProcsStatCd; scwin.vAcptNo; scwin.vSPOT_ISU_TRD_MKT_TP_CD; scwin.TR_JOB; scwin.vSECT_CHG_TP_CD = ""; com.wconv.type = ""; scwin.pLogType = ""; scwin.onpageload = function () {  	
//};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
    */
    var arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }, {
        cid: "SECT_INVSTG_TP_CD",
        cnm: "cmb_AFCHG_SECT_INVSTG_TP_CD"
    }, {
        cid: "SECT_CHG_RSN_CD",
        cnm: "cmb_SECT_CHG_RSN"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='SECT_TP_CD','SECT_TP_CD','SECT_CHG_TP_CD','SECT_INVSTG_TP_CD','SECT_CHG_RSN_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < com.wconv.length(arrCid); i++) {

	//----W-Craft WebSquare 변환 확인: getElementById----//
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.CountRow; j++) {

	//----W-Craft WebSquare 변환 확인: NameValue----//
            if (dts_Cod.NameValue(j, "CD_ENG_NM") == arrCid[i].cid) {
                if (arrCid[i].cid == "01362") {

	//----W-Craft WebSquare 변환 확인: NameValue----//
                    if (dts_Cod.NameValue(j, "VALUE") == "10") {
                        strCbd = strCbd + "^-----------------------------------------------------";
                    }
                }

	//----W-Craft WebSquare 변환 확인: NameValue----//
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.NameValue(j, "VALUE") + "^" + dts_Cod.NameValue(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_extr_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.extr.search" + "&{P}param01=" + scwin.vAcptNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_file_read_sync();
};
scwin.fn_file_read_sync = function() {
    if (scwin.vAcptNo != "") {
        //컨버젼하기가 어려워 제외됨..
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_APPROV_ATTACHFILE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.attachfile" + "&{P}param01=" + scwin.vAcptNo;
        dts_File.DataID = encodeURI(url);
        dts_File.Reset();
    } else {
        var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=SECT_TYP_CHG_CERT_ATTACHFILE_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.select.cert.attachfile" + "&{P}param01=" + scwin.vBzProcsNo;
        dts_File.DataID = encodeURI(url);
        dts_File.Reset();
    }
};
scwin.fn_read_sync = function() {
    var url = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=readMarketAction&inputMessageId=SECT_TYP_CHG_INOUT";
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_file_read_sync();
};
scwin.fn_CheckForm = function() {

	//----W-Craft WebSquare 변환 확인: cGetToday----//
    var vCurDate = cGetToday("yyyymmdd");

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(txb_ISUR_CD) == "") {
        alert("[회사코드] 항목값이  없습니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
        txb_ISUR_CD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        alert("[소속부변경구분]을 선택하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD == 'N') {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (scwin.vSECT_CHG_TP_CD != getObjectValue(cmb_SECT_CHG_TP_CD)) {
            alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            //심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_SECT_CHG_TP_CD) == "") {
        alert("[소속부변경구분]을 선택하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_SECT_CHG_TP_CD) != "N") {
        //신규상장

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (getObjectValue(cmb_BFCHG_SECT_TP_CD) == "") {
            alert("[변경전 소속부] 항목값이  없습니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_AFCHG_SECT_TP_CD) == "") {
        alert("[변경후 소속부]를 선택하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(edt_CHG_DD) == "") {
        alert("[변경일]을 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_CHG_DD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (vCurDate >= getObjectValue(edt_CHG_DD)) {
        alert("[변경일]을 현재일이후로 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        edt_CHG_DD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(edt_SECT_STRT_DD) == "") {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (getObjectValue(edt_SECT_END_DD) != "") {
            alert("[소속부유효시작일]을 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (getObjectValue(edt_SECT_END_DD) == "") {
            alert("[소속부유효종료일]을 입력하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
            edt_SECT_END_DD.focus();
            return false;
        }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (com.wconv.parseInt(getObjectValue(edt_SECT_STRT_DD), 10) > com.wconv.parseInt(getObjectValue(edt_SECT_END_DD), 10)) {
            alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_AFCHG_SECT_INVSTG_TP_CD) == "") {
        alert("[소속부 심사구분]를 선택하세요.");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_AFCHG_SECT_INVSTG_TP_CD.focus();
        return false;
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_BFCHG_SECT_TP_CD) == "4") {
        //기술성장기업부

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (getObjectValue(cmb_AFCHG_SECT_TP_CD) == "2" || getObjectValue(cmb_AFCHG_SECT_TP_CD) == "3") {
            alert("변경전 소속부가 기술성장기업부일 경우 우량기업부로 변경만 가능합니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(cmb_BFCHG_SECT_TP_CD) == "2" || //벤처 

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        getObjectValue(cmb_BFCHG_SECT_TP_CD) == "3") {
        //중견

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
        if (getObjectValue(cmb_AFCHG_SECT_TP_CD) == "4") {
            alert("변경전 소속부가 벤처나 중견일 경우 우량기업부로 변경만 가능합니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    return true;
};
scwin.fn_duplicate_check = function() {
    var url = "/SectionTypeChange.do?method=checkDuplicate&inputMessageId=SECT_TYP_CHG_DUP_CHK_OUT";

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url += "&ISUR_CD=" + getObjectValue(txb_ISUR_CD);

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    url += "&CHG_DD=" + getObjectValue(edt_CHG_DD);
    dts_DUP_CHK.DataID = encodeURI(url);
    dts_DUP_CHK.Reset();

	//----W-Craft WebSquare 변환 확인: NameValue----//
    return dts_DUP_CHK.NameValue(1, "DUP_CHK");
};


//인증자격
scwin.fn_AhthAdm = function(type) {
    if (type == "1") {
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_AHTH_ADM_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.ahthacpt.select" + "&{P}param01=" + scwin.vAcptNo;
        dts_AhthAdm.DataID = encodeURI(url);
        dts_AhthAdm.Reset();
    } else {
        var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_AHTH_ADM_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.ahthprocs.select" + "&{P}param01=" + scwin.vBzProcsNo;
        dts_AhthAdm.DataID = encodeURI(url);
        dts_AhthAdm.Reset();
    }
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (scwin.fn_duplicate_check() == 'Y') {
            alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }

	//----W-Craft WebSquare 변환 확인: fn_isProcess----//
        if (!fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_INSERT);

        /*
        vBzProcsNo = fn_getNewBzProcNo( dts_BzProcsNo );

        if (vBzProcsNo.length != 14) {

	//----W-Craft WebSquare 변환 확인: getMessageParam----//
        	alert(getMessageParam("MSG-0010", ""));
        } else {

        	//dts_Item.NameValue(1, "BZ_PROCS_NO") = vBzProcsNo;
        	//alert('[JOB_TYPE]'+dts_Item.NameValue(1, "JOB_TYPE") );
        	//alert('[vSPOT_ISU_TRD_MKT_TP_CD]'+vSPOT_ISU_TRD_MKT_TP_CD );

        	fn_trs(TR_JOB_INSERT);
        }
        */
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

	//----W-Craft WebSquare 변환 확인: fn_isProcess----//
        if (!fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_delete = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(edt_APPROV_DDTM) != "") {
        alert("승인처리가 완료된 후 삭제 할 수 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';
    if (scwin.vSECT_CHG_TP_CD == 'N') {
        alert("[소속부변경구분]값이 '신규상장'이면 삭제 할 수 없습니다.");

	//----W-Craft WebSquare 변환 확인: focus----//
        cmb_SECT_CHG_TP_CD.focus();
        return;
        //심사팀에서 신규상장시 입력한 자료라서 삭제 불가(신규상장한건도 삭제처리됨.).
    }

	//----W-Craft WebSquare 변환 확인: fn_isProcess----//
    if (!fn_isProcess(scwin.TR_JOB)) return;

	//----W-Craft WebSquare 변환 확인: setDeleteStatus----//
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.fn_trs(TR_JOB_DELETE);
};
scwin.fn_BfSectInvstgTpCd = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_INVSTG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.bfchgsectinvstgtpcd.select" + "&{P}param01=" + getObjectValue(txb_ISUR_CD);
    dts_bfSectInvstg.DataID = encodeURI(url);
    dts_bfSectInvstg.Reset();
};
scwin.fn_trs = function(jobType) {
    //소속부 변경전 심사코드 

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//

	//----W-Craft WebSquare 변환 확인: getObjectValue----//

	//----W-Craft WebSquare 변환 확인: NameValue----//
    scwin.fn_BfSectInvstgTpCd(); /*ORG SRC: dts_Item.NameValue(1, "JOB_TYPE") = jobType;*/ X = jobType; /*ORG SRC: dts_Item.NameValue(1, "ISUR_CD") = getObjectValue(txb_ISUR_CD);*/ X = getObjectValue(txb_ISUR_CD); /*ORG SRC: dts_Item.NameString(1, "LIST_BZ_TP_CD") = LIST_BZ_TP_CD_234;*/ X = LIST_BZ_TP_CD_234; /*ORG SRC: dts_Item.NameString(1, "SPOT_ISU_TRD_MKT_TP_CD") = vSPOT_ISU_TRD_MKT_TP_CD;*/ X = scwin.vSPOT_ISU_TRD_MKT_TP_CD; /*ORG SRC: dts_Item.NameString(1, "BFCHG_SECT_INVSTG_TP_CD") = dts_bfSectInvstg.NameString(1, "AFCHG_SECT_INVSTG_TP_CD");*/ X = dts_bfSectInvstg.NameString(1, "AFCHG_SECT_INVSTG_TP_CD");
    var vScrenProcTpCd;
    if (scwin.TR_JOB == "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }

    //alert('[dts_Item]'+dts_Item.text);

	//----W-Craft WebSquare 변환 확인: fn_encodeNSession----//
    trs_Save.Action = fn_encodeNSession("/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcTpCd + "&method=saveMarketAction");
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item,I:pFile1=dts_File)";

	//----W-Craft WebSquare 변환 확인: Post----//
    trs_Save.Post();
};
scwin.fn_popopSW = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=SECT_TYP_CHG_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstproc.scttypchg.revwrlog.sw.select" + "&{P}param01=" + getObjectValue(txb_ISUR_CD);
    dts_sw.DataID = encodeURI(url);
    dts_sw.Reset();
};
scwin.fn_revwr = function() {
    scwin.TR_JOB = '검토처리';
    scwin.pLogType = "1";

	//----W-Craft WebSquare 변환 확인: getMessageParam----//
    var res = window.confirm(getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('1');
    }
};
scwin.fn_approve = function() {

	//----W-Craft WebSquare 변환 확인: getObjectValue----//
    if (getObjectValue(edt_REVW_DDTM) == "") {
        alert("검토처리가 완료된 후 승인처리를 할 수 있습니다.");
        return;
    }
    scwin.TR_JOB = '승인처리';
    scwin.pLogType = "2";

	//----W-Craft WebSquare 변환 확인: getMessageParam----//
    var res = window.confirm(getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        scwin.fn_trslog('2');
    }
};
