scwin.inf_find_OnClick = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
    var filenm = file_name.getValue(); /*ORG SRC: dts_File.NameString(dts_File.rowposition, "fileInfo") = inf_find.Value;*/ X = inf_find.getValue();
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_File.countrow == 5) {
        alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_File.insertRow();

	//----W-Craft WebSquare 변환 확인: open----//
    inf_find.open();
    if (inf_find.getValue() != "") {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************


	//----W-Craft WebSquare 변환 확인: NameString----//
        /*ORG SRC: dts_File.NameString(dts_File.rowposition, "fileInfo") = inf_find.Value;*/
        X = inf_find.getValue();
        file_name.setValue(inf_find.getValue());
    } else {
        dts_File.DeleteRow(dts_File.RowPosition);
    }
};
scwin.btn_linedelete_onclick = function() {
    dts_File.deleterow(dts_File.rowposition);
};
scwin.gform_onload = function() {

	//----W-Craft WebSquare 변환 확인: PanelToGroupBox----//
    PanelToGroupBox(panel_Item);
    scwin.fn_searchCode();

	//----W-Craft WebSquare 변환 확인: Provider----//
    var parentWin = frame.Provider("../");
    scwin.vBzProcsNo = parentWin.gBzProcsNo;
    scwin.vAcptNo = parentWin.gAcptNo;
    scwin.vListProcsStatCd = parentWin.gListProcsStatCd;
    var dstOjb = parentWin.dts_List_2;
    var row = dstOjb.RowPosition;
    scwin.vSPOT_ISU_TRD_MKT_TP_CD = '2';

	//----W-Craft WebSquare 변환 확인: setObjectValue----//

	//----W-Craft WebSquare 변환 확인: NameString----//
    setObjectValue(txb_ISUR_CD, dstOjb.NameString(row, "ISUR_CD"));

	//----W-Craft WebSquare 변환 확인: setObjectValue----//

	//----W-Craft WebSquare 변환 확인: NameString----//
    setObjectValue(txb_COM_NM, dstOjb.NameString(row, "COM_ABBRV"));

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */

	//----W-Craft WebSquare 변환 확인: setSaveInfo----//
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장

	//----W-Craft WebSquare 변환 확인: setUpdateInfo----//
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정	

	//----W-Craft WebSquare 변환 확인: setDeleteInfo----//
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제


	//----W-Craft WebSquare 변환 확인: SetDataHeader----//
    dts_File.SetDataHeader("fileInfo:String,FILEURL:URL,SAVE_FILE_NM:String");

	//----W-Craft WebSquare 변환 확인: showObj----//
    showObj(file_name, false);
    if (scwin.vListProcsStatCd == "10") {
        //미처리
        scwin.fn_extr_read_sync();
        scwin.fn_AhthAdm("1");

	//----W-Craft WebSquare 변환 확인: setInsertStatus----//
        buttonSet.setInsertStatus();
        btn_Revwr.src = "../img/btn_study_d.gif";
        btn_Revwr.setDisabled(false);
        btn_Approve.src = "../img/btn_approval_d.gif";
        btn_Approve.setDisabled(false);
    } else {
        //090720-팀원은 컴토만, 팀장은 승인만 
        if (js_jobtitl == "03") {
            //팀원'03'
            btn_Revwr.src = "../img/btn_study.gif";
            btn_Revwr.setDisabled(true);
            btn_Approve.src = "../img/btn_approval_d.gif";
            btn_Approve.setDisabled(false);
        } else {
            btn_Revwr.src = "../img/btn_study_d.gif";
            btn_Revwr.setDisabled(false);
            btn_Approve.src = "../img/btn_approval.gif";
            btn_Approve.setDisabled(true);
        }
        scwin.fn_read_sync();
        scwin.fn_AhthAdm("2");
    }
};

